{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 그대로 수행하지 않고 확인이 필요하다고 판단할 수 있는지 검증한다. 진통제 투약을 중단하기로 한 판단의 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력된 상황",
          "task": "해당 처방에 따른 투약을 진행해도 되는지 판단해야 하는 상황",
          "action": "처방 용량에서 발견한 이상과 확인되지 않은 부분을 근거로 투약 중단을 판단한 내용을 설명한다.",
          "result": "처방을 그대로 수행하지 않고 투약을 멈추기로 한 판단의 근거가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "투약을 멈춰야 한다고 판단한 구체적인 근거",
          "처방 용량이 평소 용량과 달랐다는 사실을 인지한 내용",
          "용량 차이를 확인하지 않은 채 투약해서는 안 된다는 판단으로 연결한 설명"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배였던 일이 있으셨는데요, 그때 투약을 멈춰야 한다고 판단한 근거는 무엇이었어요?",
      "answerTip": "당시 상황을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방 용량과 평소 용량의 차이를 구체적으로 짚어 투약 중단의 근거를 설명한다.",
            "용량 차이가 확인되지 않은 상태에서 투약을 진행할 수 없다는 판단의 연결이 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 처방 용량을 보고 투약을 멈췄다는 핵심 근거는 제시한다.",
            "용량 차이가 투약 중단 판단으로 이어진 설명은 다소 포괄적이다."
          ]
        },
        "poor": {
          "criteria": [
            "투약 중단의 근거를 제시하지 못하거나 처방 용량의 차이와 무관한 내용만 답한다.",
            "확인되지 않은 용량 차이를 인지하고도 투약을 진행해도 된다는 판단을 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태를 간호 기록에 정확히 옮길 수 있는지 검증한다. 수술 후 환자의 관찰 내용을 기록으로 남길 때 실제로 중점을 둔 판단에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 활력징후와 통증을 관찰하고 간호 기록을 작성한 업무 상황",
          "task": "관찰한 환자 상태가 정확히 드러나도록 간호 기록을 남겨야 하는 상황",
          "action": "기록에서 가장 신경 쓴 점을 자신이 관찰한 내용과 연결하여 설명한다.",
          "result": "관찰한 상태를 정확한 기록으로 옮기기 위해 중점을 둔 부분이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "관찰한 환자 상태를 정확히 기록하기 위해 가장 신경 쓴 점",
          "그 중점을 실제 기록에 반영한 방식",
          "해당 방식이 관찰 사실이나 상태 변화를 정확하게 드러내는 이유"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 활력징후와 통증을 간호 기록에 남기셨던데요, 관찰한 상태를 정확히 기록하기 위해 가장 신경 쓰신 점은 뭐였어요?",
      "answerTip": "직접 하셨던 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "환자 상태를 정확히 기록하기 위해 중점을 둔 부분을 명확하게 제시한다.",
            "그 중점을 실제 기록에 반영한 방식을 구체적으로 설명한다.",
            "기록 방식이 관찰 사실이나 상태 변화를 정확하게 드러내는 이유가 타당하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "정확한 기록을 위해 신경 쓴 부분은 제시한다.",
            "실제 기록에 반영한 방식이나 관찰 사실의 정확성과 연결되는 설명은 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "기록에서 신경 쓴 부분을 제시하지 못하고 업무 소개나 기록의 중요성만 설명한다.",
            "실제 기록 방식이 드러나지 않거나 관찰 사실과 추정을 구분하지 않는 등 정확한 기록과 어긋나는 설명을 한다."
          ]
        }
      }
    }
  ]
}
